def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    original = [row[:] for row in g]

    # Extend horizontal bars using a vertical color sequence beside them.
    for r in range(h):
        c = 0
        while c < w:
            if original[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and original[r][c] == 5:
                c += 1
            b = c - 1
            for dr in (-1, 1):
                side = r + dr
                if not (0 <= side < h):
                    continue
                for sc in range(a, b + 1):
                    if original[side][sc] == 0:
                        continue
                    seq = []
                    rr = side
                    while 0 <= rr < h and original[rr][sc] != 0:
                        seq.append((rr, original[rr][sc]))
                        rr += dr
                    for cc in range(a, b + 1):
                        for rr0, val in seq:
                            if original[rr0][cc] == 0:
                                g[rr0][cc] = val

    # Extend vertical bars using horizontal color patterns beside them.
    for c in range(w):
        r = 0
        while r < h:
            if original[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and original[r][c] == 5:
                r += 1
            b = r - 1
            for dc in (-1, 1):
                side = c + dc
                if not (0 <= side < w):
                    continue
                seed_rows = [rr for rr in range(a, b + 1)
                             if original[rr][side] != 0]
                if not seed_rows:
                    continue
                # Consecutive colored rows form the repeating template.
                groups = []
                for rr in seed_rows:
                    if not groups or rr != groups[-1][-1] + 1:
                        groups.append([rr])
                    else:
                        groups[-1].append(rr)
                for group in groups:
                    templates = []
                    for rr in group:
                        vals = []
                        cc = side
                        while 0 <= cc < w and original[rr][cc] != 0:
                            vals.append((cc, original[rr][cc]))
                            cc += dc
                        templates.append(vals)
                    for rr in range(a, b + 1):
                        idx = (rr - group[0]) % len(group)
                        for cc, val in templates[idx]:
                            if original[rr][cc] == 0:
                                g[rr][cc] = val
    return g
